function History({ user, catalog, onOpen }: { user: User; catalog: Catalog; onOpen: (id: string) => void }) {
  const [from, setFrom] = useState(`${today().slice(0, 7)}-01`); const [to, setTo] = useState(today()); const [unit, setUnit] = useState(''); const [search, setSearch] = useState(''); const [type, setType] = useState(''); const [status, setStatus] = useState('');
  const { trips, loading, error } = useTrips('history', user.id, { from, to, unitId: unit }); const rows = trips.filter(trip => (!type || trip.type === type) && (!status || trip.status === status) && (!search || [trip.code, trip.plate, trip.destination, trip.driver1Name, trip.driver2Name].join(' ').toLowerCase().includes(search.toLowerCase())));
  return <><PageHeader eyebrow="REGISTROS QUE CONTAM A HISTÓRIA" title="Histórico de viagens" description="Consulte etapas, tempos, documentos e o histórico preservado da operação." actions={<a className="button button-secondary" href={`/api/reports/trips.csv?${query({ from, to, unitId: unit, type, status, search })}`}><Icon name="download" />Exportar CSV</a>} /><div className="panel history-filters"><div className="filter-bar"><Field label="De"><input type="date" value={from} onChange={event => setFrom(event.target.value)} /></Field><Field label="Até"><input type="date" min={from} value={to} onChange={event => setTo(event.target.value)} /></Field><Field label="Unidade"><UnitSelect catalog={catalog} value={unit} onChange={setUnit} /></Field><Field label="Tipo"><select value={type} onChange={event => setType(event.target.value)}><option value="">Todos os tipos</option><option value="PULL">Puxada</option><option value="TRANSFER">Transferência</option></select></Field><Field label="Situação"><select value={status} onChange={event => setStatus(event.target.value)}><option value="">Todas</option><option value="ARRIVED">Concluída</option><option value="IN_PROGRESS">Em andamento</option><option value="CANCELLED">Cancelada</option></select></Field></div><div className="history-search"><Icon name="search" /><input aria-label="Buscar viagens" value={search} onChange={event => setSearch(event.target.value)} placeholder="Buscar placa, viagem, destino ou motorista" /><span>{rows.length} resultados</span></div></div><ErrorBox error={error} /><div className="panel">{loading ? <div className="loading-card">Buscando histórico…</div> : !rows.length ? <Empty icon="history" title="Nenhuma viagem neste filtro">Ajuste o período ou os filtros para consultar outros registros.</Empty> : <div className="table-wrap"><table><thead><tr><th>Viagem / placa</th><th>Unidade / destino</th><th>Motoristas</th><th>Saída</th><th>Chegada</th><th>Situação</th><th /></tr></thead><tbody>{rows.map(trip => <tr key={trip.id}><td><strong>{trip.code}</strong><small>{trip.plate} · {trip.type === 'TRANSFER' ? 'Transferência' : 'Puxada'}</small>{trip.imported && <span className="imported-label">Histórico importado</span>}</td><td><strong>{trip.destination}</strong><small>{trip.unitName}</small></td><td>{trip.driver1Name}<small>{trip.driver2Name || 'Solo'}</small></td><td>{dateTime(trip.startedAt)}</td><td>{dateTime(trip.endedAt)}</td><td><Badge tone={trip.status === 'ARRIVED' ? 'green' : trip.status === 'IN_PROGRESS' ? 'blue' : 'neutral'}>{statusLabel[trip.status]}</Badge></td><td><button className="icon-button" aria-label={`Abrir viagem ${trip.code}`} onClick={() => onOpen(trip.id)}><Icon name="arrow" /></button></td></tr>)}</tbody></table></div>}</div></>;
}

function SettingsPage({user,catalog,reload}:{user:User;catalog:Catalog;reload:()=>Promise<void>}) {
  const [tab,setTab]=useState(user.canConfigure===false?'goals':'operation');
  return <><PageHeader title="Configurações da Puxada" description="Cadastros, regras da operação e metas." actions={user.role==='ADMIN'?<button className="button button-secondary" onClick={()=>window.parent.DISB_PULL_APP?.openAdministration()}>Usuários e permissões</button>:undefined}/><div className="tabs settings-page-tabs">{user.canConfigure!==false&&<button className={tab==='operation'?'active':''} onClick={()=>setTab('operation')}>Cadastros e operação</button>}{user.canEditGoals&&<button className={tab==='goals'?'active':''} onClick={()=>setTab('goals')}>Metas</button>}</div>{tab==='goals'?<GoalSettings/>:<Settings user={user} catalog={catalog} reload={reload}/>}</>;
}
function Settings({ user, catalog, reload }: { user: User; catalog: Catalog; reload: () => Promise<void> }) {
  const [tab, setTab] = useState('operation'); const [error, setError] = useState(''); const [success, setSuccess] = useState(''); const [busy, setBusy] = useState(false); const [editing, setEditing] = useState<Data | null>(null); const [newRecord, setNewRecord] = useState(false); const [questions, setQuestions] = useState<Data[]>(catalog.questions); const [questionText, setQuestionText] = useState('');
  useEffect(() => setQuestions(catalog.questions), [catalog.questions]);
  const tabs = [{ key: 'operation', label: 'Operação' }, { key: 'vehicles', label: 'Veículos' }, { key: 'factories', label: 'Fábricas' }, ...[]];
  async function toggleChecklist(enabled: boolean) { setBusy(true); setError(''); setSuccess(''); try { await api.put('/settings', { ...catalog.settings, checklistEnabled: enabled }); await reload(); setSuccess(enabled ? 'Checklist habilitado para novas programações.' : 'Checklist desligado. Nenhuma etapa exige seu preenchimento enquanto estiver desligado.'); } catch (error) { setError(message(error)); } finally { setBusy(false); } }
  async function saveQuestions() { setBusy(true); setError(''); try { await api.put('/questions', questions.map((question, index) => ({ ...question, order: index + 1 }))); await reload(); setSuccess('Perguntas salvas para os próximos checklists.'); } catch (error) { setError(message(error)); } finally { setBusy(false); } }
  const records: Data[] = tab === 'users' ? catalog.users : tab === 'vehicles' ? catalog.vehicles : tab === 'factories' ? catalog.factories : catalog.units;
  return <><div className="panel settings-panel"><div className="tabs">{tabs.map(item => <button key={item.key} onClick={() => { setTab(item.key); setSuccess(''); setError(''); }} className={tab === item.key ? 'active' : ''}>{item.label}</button>)}</div><ErrorBox error={error} />{success && <div className="notice notice-success" role="status"><Icon name="check" />{success}</div>}{tab === 'operation' ? <div className="settings-content"><div className="settings-intro"><div className="summary-icon"><Icon name="shield" size={25} /></div><div><h2>Checklist de veículo</h2><p>Uma conferência simples de saída e retorno, sem interromper a operação.</p></div><button type="button" className={`toggle ${catalog.settings.checklistEnabled ? 'enabled' : ''}`} role="switch" aria-checked={!!catalog.settings.checklistEnabled} aria-label="Habilitar checklist" disabled={busy} onClick={() => void toggleChecklist(!catalog.settings.checklistEnabled)}><span /></button></div><div className="setting-status"><Badge tone={catalog.settings.checklistEnabled ? 'green' : 'neutral'}>{catalog.settings.checklistEnabled ? 'Habilitado' : 'Desligado'}</Badge><p>{catalog.settings.checklistEnabled ? 'Novas viagens terão checklist nas etapas previstas. As perguntas e a regra ficam preservadas em cada viagem.' : 'As viagens seguem sem exigir checklist. Novas programações dispensam classificação semanal. Os históricos permanecem preservados.'}</p></div>{<section className="questions-editor"><div className="section-heading"><h3>Perguntas da conferência</h3><span className="muted">Respostas OK / NOK</span></div>{questions.map((question, index) => <div className="question-editor-row" key={question.id}><span className="question-order">{index + 1}</span><input aria-label={`Pergunta ${index + 1}`} value={question.text} onChange={event => setQuestions(current => current.map(item => item.id === question.id ? { ...item, text: event.target.value } : item))} /><label><input type="checkbox" checked={!!question.critical} onChange={event => setQuestions(current => current.map(item => item.id === question.id ? { ...item, critical: event.target.checked } : item))} />Atenção</label><button className="icon-button" aria-label={`Remover pergunta ${index + 1}`} onClick={() => setQuestions(current => current.filter(item => item.id !== question.id))}><Icon name="close" size={17} /></button></div>)}<div className="new-question"><input aria-label="Nova pergunta" placeholder="Digite uma nova pergunta" value={questionText} onChange={event => setQuestionText(event.target.value)} /><button className="button button-secondary" disabled={!questionText.trim()} onClick={() => { setQuestions(current => [...current, { id: uid(), text: questionText.trim(), critical: false, active: true, order: current.length + 1 }]); setQuestionText(''); }}><Icon name="plus" />Adicionar</button></div><button className="button button-primary" disabled={busy || questions.some(question => !question.text.trim())} onClick={() => void saveQuestions()}>Salvar perguntas<Icon name="check" /></button></section>}<div className="gps-setting"><Icon name="pin" /><div><strong>Localização com prazo de 10 segundos</strong><p>Ao final do prazo, a etapa pode ser registrada sem posição. Analistas e administradores podem complementar depois, com auditoria.</p></div><Badge tone="blue">10 segundos</Badge></div></div> : <><div className="panel-header"><div><h2>{tabs.find(item => item.key === tab)?.label}</h2><p>{records.length} registros disponíveis</p></div><button className="button button-primary" onClick={() => { setEditing(null); setNewRecord(true); }}><Icon name="plus" />Adicionar</button></div>{records.length ? <div className="table-wrap"><table><thead><tr><th>{tab === 'vehicles' ? 'Placa' : 'Nome'}</th><th>{tab === 'users' ? 'Usuário / perfil' : tab === 'vehicles' ? 'Transportadora' : 'Detalhes'}</th><th>Situação</th><th /></tr></thead><tbody>{records.map(record => <tr key={record.id}><td><strong>{record.plate || record.name}</strong></td><td>{tab === 'users' ? `${record.username} · ${roleLabel[record.role] || record.role}` : tab === 'vehicles' ? record.carrier || '—' : record.address || record.code || '—'}</td><td><Badge tone={record.active !== false ? 'green' : 'neutral'}>{record.active !== false ? 'Ativo' : 'Inativo'}</Badge></td><td><button className="button button-text" onClick={() => { setEditing(record); setNewRecord(true); }}>Editar</button></td></tr>)}</tbody></table></div> : <Empty icon={tab === 'vehicles' ? 'truck' : 'file'} title="Nenhum cadastro por aqui">Adicione o primeiro registro para começar.</Empty>}</>}</div>{newRecord && <RegistryForm kind={tab} initial={editing} catalog={catalog} onClose={() => setNewRecord(false)} onSaved={() => { setNewRecord(false); void reload(); setSuccess('Cadastro salvo.'); }} />}</>;
}
function RegistryForm({ kind, initial, catalog, onClose, onSaved }: { kind: string; initial: Data | null; catalog: Catalog; onClose: () => void; onSaved: () => void }) {
  const [form, setForm] = useState<Data>({ name: '', username: '', password: '', role: 'DRIVER', unitIds: [], unitId: '', plate: '', carrier: '', address: '', code: '', active: true, ...initial }); const [error, setError] = useState(''); const [busy, setBusy] = useState(false); const set = (key: string, value: any) => setForm(current => ({ ...current, [key]: value }));
  const noun = ({ users: 'usuário', vehicles: 'veículo', factories: 'fábrica', units: 'unidade' } as Record<string, string>)[kind];
  return <Modal title={`${initial ? 'Editar' : 'Adicionar'} ${noun}`} onClose={onClose}><form className="modal-body" onSubmit={async event => { event.preventDefault(); setBusy(true); setError(''); try { const payload = { ...form }; if (!payload.password) delete payload.password; if (initial) await api.put(`/${kind}/${initial.id}`, payload); else await api.post(`/${kind}`, payload); onSaved(); } catch (error) { setError(message(error)); } finally { setBusy(false); } }}>
    {kind === 'vehicles' ? <><Field label="Placa"><input required value={form.plate} onChange={event => set('plate', event.target.value.toUpperCase())} placeholder="ABC1D23" maxLength={8} /></Field><Field label="Transportadora"><input value={form.carrier} onChange={event => set('carrier', event.target.value)} /></Field></> : <Field label="Nome"><input required readOnly={kind==='factories'&&!!initial} value={form.name} onChange={event => set('name', event.target.value)} /></Field>}
    {kind === 'users' && <><div className="form-grid"><Field label="Usuário"><input required autoComplete="off" value={form.username} onChange={event => set('username', event.target.value)} /></Field><Field label="Perfil"><select value={form.role} onChange={event => set('role', event.target.value)}><option value="DRIVER">Motorista</option><option value="ANALYST">Analista</option><option value="ADMIN">Administrador</option></select></Field></div><Field label={initial ? 'Nova senha (opcional)' : 'Senha inicial'} hint="Use pelo menos 12 caracteres."><input type="password" required={!initial} minLength={12} autoComplete="new-password" value={form.password || ''} onChange={event => set('password', event.target.value)} /></Field><div className="field"><span>Unidades de acesso</span><div className="unit-checks">{catalog.units.map(unit => <label key={unit.id}><input type="checkbox" checked={form.unitIds?.includes(unit.id)} onChange={event => set('unitIds', event.target.checked ? [...(form.unitIds || []), unit.id] : form.unitIds.filter((id: string) => id !== unit.id))} />{unit.name}</label>)}</div></div></>}

    {kind === 'factories' && <><div className="form-grid"><Field label="Latitude (opcional)"><input type="number" step="any" min="-90" max="90" value={form.latitude ?? ''} onChange={event => set('latitude', event.target.value === '' ? null : Number(event.target.value))} /></Field><Field label="Longitude (opcional)"><input type="number" step="any" min="-180" max="180" value={form.longitude ?? ''} onChange={event => set('longitude', event.target.value === '' ? null : Number(event.target.value))} /></Field></div><Field label="Raio de referência (metros)"><input type="number" min="1" value={form.radiusMeters ?? ''} onChange={event => set('radiusMeters', event.target.value === '' ? null : Number(event.target.value))} /></Field></>}<label className="checkbox-field"><input type="checkbox" checked={form.active} onChange={event => set('active', event.target.checked)} /><span>Cadastro ativo</span></label><ErrorBox error={error} /><div className="modal-actions"><button type="button" className="button button-secondary" onClick={onClose}>Voltar</button><button className="button button-primary" disabled={busy}>{busy ? 'Salvando…' : 'Salvar cadastro'}<Icon name="check" /></button></div></form></Modal>;
}
